namespace sv_f7cf662bc879495a871a5c1b8ae34a42.Services;

public record EquipmentItem(int Id, string Name, string Location, DateOnly LastInspected);

public class EquipmentService
{
    private static readonly EquipmentItem[] Items =
    [
        new(1, "Forklift A", "Warehouse 1", new DateOnly(2026, 6, 15)),
        new(2, "Conveyor Belt", "Warehouse 2", new DateOnly(2026, 5, 22)),
        new(3, "Pallet Jack B", "Loading Dock", new DateOnly(2026, 7, 1)),
        new(4, "Overhead Crane", "Warehouse 1", new DateOnly(2026, 4, 10)),
        new(5, "Shrink Wrapper", "Packaging Area", new DateOnly(2026, 3, 30)),
        new(6, "Label Printer", "Shipping Desk", new DateOnly(2026, 6, 28)),
        new(7, "Barcode Scanner", "Receiving Dock", new DateOnly(2026, 7, 5)),
    ];

    public async Task<EquipmentItem[]> GetEquipmentAsync()
    {
        await Task.Delay(500); // simulate latency
        return Items;
    }
}

@page "/inventory"
@rendermode InteractiveServer
@inject EquipmentService EquipmentSvc

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (Items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in Items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToString("yyyy-MM-dd")</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [PersistentState]
    public EquipmentItem[]? Items { get; set; }

    protected override async Task OnInitializedAsync()
    {
        Items ??= await EquipmentSvc.GetEquipmentAsync();
    }
}

